def _group_escape(observer, site):
    try:
        yield
    except BaseException as error:
        if observer is not None:
            try:
                tag = _group_exception_tag(error)
            except BaseException:
                tag = "unclassified"
            try:
                observer(site, tag)
            except BaseException:
                pass
        raise

