def open(self, name, parent=None, directory=False, magic=False):
    self.budget.fd()
    flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK
    if directory:
        flags |= os.O_DIRECTORY
    if not magic:
        flags |= os.O_NOFOLLOW
    return self.own(os.open(name, flags, dir_fd=parent))

